UPDATE companies SET description='Hayden Valley Foods operates from Urbancrest, Ohio, where it was founded in 1966 by Garland Williamson. The company remains family-owned, having grown from a relationship-driven business across the South into a large-scale snack and confection manufacturing partner.

The 150,000-square-foot facility integrates roasting, coating and enrobing, mixing and custom blending, packaging, distribution, and product development under one roof. Capabilities include nut and snack ingredient roasting, chocolate and yogurt coatings, trail mix formulation, and flexible retail and foodservice packaging, supporting scalable batch production for high-volume programs.

The company serves brands, retailers, distributors, and private-label partners in the snack and confection sectors. Its offerings span bulk ingredient supply, private label manufacturing, branded snack programs, and seasonal and gifting solutions, with end-to-end supply chain support from concept to shelf.

Hayden Valley Foods emphasizes family-owned accountability, integrity, and partnership as its differentiators. The company combines those values with modern production systems and certified quality standards—SQF, BC Probiotic, Kosher, and FDA registration—to deliver consistency and speed from idea to commercialization.', certifications=ARRAY['SQF','BC Probiotic','Kosher','FDA Registered']::text[], profile='{"capabilities": ["Roasting", "Coating & Enrobing", "Mixing & Custom Blending", "Packaging", "Distribution", "Product Development", "Bulk Supply", "Private Label Manufacturing", "Branded Product Manufacturing", "Seasonal & Gifting Programs", "Trail Mix Formulation", "Snack & Nut Blends", "Custom Ingredient Combinations", "Retail & Foodservice Packaging", "Fulfillment & Logistics", "Concept Development", "Ingredient Selection", "Sampling & Refinement", "Commercialization Support"], "industries": ["Snack Manufacturing", "Confection Manufacturing", "Private Label", "Retail", "Foodservice", "Seasonal & Gifting"], "materials": ["Nuts", "Snack Ingredients", "Fruits", "Inclusions", "Chocolate", "Yogurt", "Flavored Coatings"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned accountability and long-term perspective", "Integrated roasting, coating, packaging, and distribution under one roof", "SQF, BC Probiotic, Kosher certified, and FDA registered", "Scalable batch production with product-specific roast development", "End-to-end supply chain support from concept to fulfillment"], "facts_used": ["Founded 1966 -> db", "Headquarters Urbancrest, Ohio -> db", "Family-owned -> /about-us", "Founder Garland Williamson -> /", "150,000+ sq ft facility -> /", "Capabilities: roasting, coating, mixing, packaging, distribution, product development -> /capabilities", "Certifications: SQF, BC Probiotic, Kosher, FDA Registered -> /capabilities", "Industries: snack and confection manufacturing, brands, retailers, distributors, private-label -> /a