UPDATE companies SET description='Headwaters Woodworking operates from Lafayette in Boulder County, Colorado, just north of Denver. The shop was founded in 2023 by Preston Brown, who built his first dining table as a legacy for his son—a piece meant to gather family daily and create lasting memories.

The company produces handcrafted custom hardwood furniture, including dining tables, benches, chairs, and kitchen and living room pieces. The shop serves both residential and commercial clients, delivering finished pieces throughout the Denver metropolitan area and the broader Front Range, from Fort Collins to Colorado Springs.

Customers range from homeowners seeking heirloom-quality dining sets to businesses furnishing offices and hospitality spaces. The shop has supplied custom tables and seating for clients across Boulder, Louisville, Erie, Westminster, and mountain communities in Summit and Clear Creek counties. Orders are taken through a consultation process where clients specify style, materials, and dimensions.

Brown started the business to help families slow down and reconnect around furniture built to last generations. The company emphasizes personal design collaboration, sustainable material sourcing, and local delivery as its defining attributes.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Handcrafted woodworking", "Wood selection and sourcing", "Furniture delivery and installation", "Client consultation"], "industries": ["Residential furniture", "Commercial furniture", "Hospitality furniture", "Interior design"], "materials": ["American hardwoods", "Reclaimed specialty woods", "Sustainably sourced woods"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 2023 by Preston Brown -> db", "Located in Lafayette, Boulder County, Colorado -> db and /", "Handcrafted custom hardwood furniture: dining tables, benches, chairs, kitchen and living room furniture -> /", "Materials: premium sustainably sourced American hardwoods and reclaimed specialty woods -> /", "Serves Denver metro area and Front Range -> /", "Custom design collaboration and delivery -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Headwaters Woodworking is a small furniture shop located in Boulder County... We specialize in handcrafted, custom hardwood furniture", "founded_year": "2023", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='headwaters-woodworking' AND approved AND profile IS NULL;
UPDATE companies SET description='Heintz Steel & Manufacturing Company operates from a 30,000-square-foot facility on Hall Street in St. Louis, Missouri. The business was founded in 1924 by William Heintz and has remained in continuous operation for over nine decades, making it one of the area’s longest-running industrial fabricators.

The shop provides custom metal fabrication including cutting, shearing, rolling, forming, and welding (MIG, TIG, and stick) on ferrous and non‑ferrous metals such as aluminum, cast iron, hardened steel, mild steel, and stainless steel. Equipment includes automatic saws, press brakes, angle rolls, plate rolls, and burning centers, all driven by CAD/CAM and computerized controllers. Welding procedures are AWS certified.

Heintz serves industrial customers requiring large‑scale fabrications; the company emphasizes a “bigger is better” philosophy to handle oversized parts. Its workforce is largely trained in‑house and works under a partnership with Shopmen’s Local 518 of the International Association of Bridge, Structural and Ornamental Iron Workers.', certifications=ARRAY['AWS Certified (welding)']::text[], profile='{"capabilities": ["Custom metal fabrication", "Cutting", "Shearing", "Rolling", "Forming", "Welding (MIG, TIG, Stick)", "Flame cutting", "CAD/CAM design", "Automatic sawing", "Press brake forming", "Angle rolling", "Plate rolling", "Burning (plasma/oxy-fuel)"], "industries": [], "materials": ["Aluminum", "Cast Iron", "Hardened Steel", "Mild Steel", "Stainless Steel"], "equipment": ["Automatic Saws", "Press Brakes", "Angle Rolls", "Plate Rolls", "Burning Centers"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["30,000 sq ft facility for large-scale fabrication", "AWS certified welding (MIG, TIG, stick)", "In-house trained workforce with union partnership (Shopmen\u2019s Local 518)", "CAD/CAM and computerized controllers for precision", "Capability to produce larger metal fabrications (''bigger is better'')"], "facts_used": ["Founded in 1924 by William Heintz -> /about", "Located at 3300 Hall Street, St. Louis, MO 63147 -> /", "30,000 sq ft facility -> /", "Equipment: Automatic Saws, Press Brakes, Angle Rolls, Plate Rolls, Burning Centers -> /", "Services: Cutting, Shearing, Rolling, Forming, Welding (MIG, TIG, Stick) -> /", "Materials: Aluminum, Cast Iron, Hardened Steel, Mild Steel, Stainless Steel -> /", "AWS Certified welding -> /", "Union relationship with Shopmen\u2019s Local 518 -> /about", "Employees trained in-house -> /about", "CAD/CAM and computerized controllers -> /about", "''Bigger is better'' philosophy for large fabrications -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom metal fabrication and design to suit our customer\u2019s specific needs is what we do best.", "founded_year": "1924", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='heintz-steel-manufacturing-company' AND approved AND profile IS NULL;
UPDATE companies SET description='Hemeixin Electronics Co., Ltd is headquartered in San Jose, California, with its own state-of-the-art PCB fabrication facilities in China. The company''s founding year and ownership structure are not publicly disclosed. It was established to provide quick-turn prototype, low-volume, and production printed circuit boards with a personalized one-stop service model.

The company manufactures rigid, flexible, and rigid-flex PCBs, including high-density interconnect (HDI) boards up to 58 layers, high-frequency and microwave circuits, heavy copper designs up to 30 oz, and boards with blind/buried vias, microvias, via-in-pad, cavity structures, and back drilling. It also offers in-house PCB assembly (SMT, through-hole, turnkey, consigned) and design-for-manufacturability checks. Standard lead times are advertised as fast as 72 hours for quick-turn orders, with full turnkey service within five days.

Hemeixin serves customers in portable communications, networking equipment, high-speed digital, and RF/microwave applications. Its materials portfolio includes polyimide (Kapton), PET, PEN, LCP, and a wide range of low-loss and high-speed laminates from Isola, Rogers, Arlon, Taconic, and Panasonic. The company''s capabilities target designs requiring fine-line traces down to 0.002 inch, BGA pitches to 0.15 mm, and impedance control within ±5%.

