UPDATE companies SET description='Indianapolis Wire & Terminal operates from Beech Grove, Indiana, where it has served as a wholesale electrical distributor for over 30 years. The company was founded as Indianapolis Wire and Terminal Inc. and remains a privately held business, though ownership details and founder names are not publicly disclosed.

The firm stocks a broad range of electrical supplies, including wire from 22 AWG to 4/0 AWG (battery cable, welding cable, trailer cable, GXL automotive wire, MTW, THHN, and control cable), terminals in non‑insulated, PVC‑insulated, nylon‑insulated, and heat‑shrink styles, plus accessories such as wire ties, fuses, loom, shrink tubing, LED lighting, switches, relays, circuit breakers, and terminal blocks.

IWT sells nationwide to manufacturers and other wholesale buyers, with notable demand from the automotive, emergency‑vehicle, and general industrial sectors. Product images on the company’s site show fire‑truck and ambulance applications, and the catalog includes GXL automotive wire and emergency LED lighting tailored to those markets.

The company’s stated differentiator is its motto, “Where Quality Starts and Service Begins,” backed by a $50 minimum order, net‑30 terms for approved accounts, and a policy of not selling to the public. IWT positions itself as a customer‑focused partner that aims to be an indispensable part of getting jobs done on time and within budget.', certifications=ARRAY['RoHS']::text[], profile='{"capabilities": ["Wholesale distribution of electrical wire, terminals, and accessories", "Inventory stocking and quick shipment", "Customer-focused sales support"], "industries": ["Electrical", "Automotive", "Emergency vehicles", "Industrial", "Manufacturing"], "materials": ["Copper wire", "PVC insulation", "Nylon insulation", "Heat shrink tubing", "Zinc-plated terminals"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Stocks all inventory for quick response and delivery", "Minimum order $50", "Net 30 payment terms for approved accounts", "Wholesale-only, no retail sales", "Over 30 years in business"], "facts_used": ["Location: Beech Grove, Indiana -> db", "Business type: wholesale electrical distributor -> /", "Years in business: over 30 years -> /", "Motto: Where Quality Starts and Service Begins -> /", "Product range: wire 22AWG-4/0AWG, terminals, accessories -> /", "Industries served: automotive, emergency vehicles, industrial -> /", "Minimum order: $50 -> /about", "Payment terms: Net 30 days -> /about", "Wholesale only, no retail -> /about", "Certification: RoHS -> db", "Sales and production team mentioned -> /"], "company_type": "Distributor / reseller", "makes_products": "unclear", "type_evidence": "Please Note Indianapolis Wire and Terminal Inc. is a Wholesale Distributor we are not open to the public and we do not do any retail sales.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "$50", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='indianapolis-wire-terminal' AND approved AND profile IS NULL;
UPDATE companies SET description='Industrial Electronics, Inc. has been operating in Honolulu, Hawaii since 1958. The family-owned business was established to supply electrical and electronic components to the Hawaiian Islands, and it remains locally owned and operated today.

The company stocks a broad range of wire and cable products, including fiber optic cabling (singlemode and multimode), coaxial cables such as LMR400 and RG8, and a variety of connectors from terminals to RF types. It also carries LAN products, network cabling, test equipment from brands like Fluke, power supplies, relays, switches, and lighting components. Industrial Electronics offers same-day shipping on stocked items, cuts fiber cable to order, and provides fiber termination supplies including 3M Hotmelt and Unicam kits. A counter opens at 6:00 AM for contractors picking up material before heading to job sites.

Customers span building automation and HVAC, home automation, CCTV and security, voice and data communications, and access control systems. The company serves electrical contractors, low-voltage installers, and facility maintenance teams across the Hawaiian Islands.

Industrial Electronics emphasizes product knowledge, competitive pricing, and product availability as core differentiators.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Electronic component distribution", "Wire and cable distribution", "Fiber optic cable and connector distribution", "Test equipment distribution", "Same-day shipping", "Custom cable cutting (fiber cut to order)", "Fiber optic termination supplies (3M Hotmelt, Unicam, anaerobic)", "Early morning counter service (6 AM)", "Product technical support"], "industries": ["Building automation", "HVAC", "Home automation", "CCTV/Security", "Voice and data communications", "Access control", "Electrical construction", "Telecommunications"], "materials": ["Copper wire and cable", "Fiber optic cable (singlemode, multimode)", "Coaxial cable (LMR400, RG8, RG213)", "Various connector types (N, F, SMA, TNC, UHF, BNC)"], "equipment": [], "volume": "", "lead_time": "Same-day shipping for stocked items", "tolerances": "", "built_on": ["Same-day shipping on stocked items", "Counter opens at 6:00 AM for early pickup", "Family-owned and operated", "Fiber optic cable cut to order and termination supplies", "Broad inventory of wire, cable, connectors, and test equipment"], "facts_used": ["Founded 1958 in Honolulu, Hawaii -> db, /about", "Family-owned and operated -> /about", "Serves Hawaiian Islands -> /about", "Same-day shipping -> /about", "Opens at 6:00 AM for counter pickup -> /about", "Product categories: wire & cable, fiber optic, connectors, test equipment, etc. -> /", "Industries: building automation, HVAC, home automation, CCTV/security, voice & data, access control -> /", "Custom cable cutting (fiber cut to order) -> /", "Fiber termination supplies (3M Hotmelt, Unicam, anaerobic) -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We are Hawaii''s leader in wiring, fiber optic cabling and connectors, LAN products, network cabling, test equipment and much more.",