UPDATE companies SET description='Ironwood Plastics Inc. was founded in 1979 by Gordon K. Stephens in Ironwood, Michigan. The company was acquired by CTB, Inc., a Berkshire Hathaway subsidiary, in 2010 and operates today as a division of that organization. A second production site was established in Two Rivers, Wisconsin, giving the company a dual-facility footprint in the Upper Midwest.

The company specializes in custom injection molding with a focus on complex, high-precision processes. Its core capabilities include two-shot molding, reel-to-reel molding, insert molding, close-tolerance molding, and overmolding. A scientific, data-driven approach to process development and optimization underpins production, and secondary services such as pad printing, sonic welding, and tape-and-reel packaging provide a single-source solution. The management team brings more than 200 years of combined plastics-industry experience.

Primary markets served are automotive, electronics, and medical. Automotive projects have included HVAC damper components, fuel-pressure sensors, cylinder-deactivation valves, and inlet check valves for plastic fuel tanks. Electronics work centers on reel-to-reel insert-molded connectors and sensor components requiring zero-defect quality. Medical applications are referenced in the context of tight-tolerance molding for critical devices.

Ironwood''s stated vision since inception has been "to be a world class injection molder of complex projects." The company differentiates itself through its engineering-driven methodology, investment in in-line inspection and vision-assisted automation, and a partnership model that emphasizes traceability from resin receipt through finished product.', certifications=ARRAY['ISO 9001:2015','IATF 16949:2016','ITAR Compliant']::text[], profile='{"capabilities": ["Two-shot molding", "Reel-to-reel molding", "Insert molding", "Close-tolerance molding", "Overmolding", "Pad printing", "Sonic welding", "Tape-and-reel packaging", "Scientific molding/process optimization"], "industries": ["Automotive", "Electronics", "Medical"], "materials": ["HDPE", "POM", "Engineered resins", "High-temperature resins"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Data-driven scientific molding process development and optimization", "One-stop secondary services: pad printing, sonic welding, tape-and-reel packaging", "Over 200 years of combined management experience in plastics", "Specialization in insert molding and engineered/high-temperature resins", "ITAR compliance and IATF 16949/ISO 9001 certification"], "facts_used": ["Founded 1979 by Gordon K. Stephens -> /about-us", "Sold to CTB, Inc. (Berkshire Hathaway) in 2010 -> /about-us", "Facilities in Ironwood, Michigan and Two Rivers, Wisconsin -> /about-us", "Certifications: ISO 9001:2015, IATF 16949:2016, ITAR Compliant -> /about-us", "Capabilities: Two-shot molding, Reel-to-reel molding, Insert molding, Close-tolerance molding, Overmolding -> /capabilities", "Secondary services: pad printing, sonic welding, tape-and-reel packaging -> /capabilities", "Management staff with over 200 years combined experience -> /about-us", "Industries served: automotive, electronics, medical -> /capabilities", "Vision: ''To be a world class injection molder of complex projects'' -> /about-us", "Data-driven scientific approach to process development -> /capabilities", "Case studies: automotive HVAC damper, fuel pressure sensors, cylinder deactivation, inlet check valve, reel-to-reel electronic components -> /capabilities"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our state-of-the-art facilities deliver the highest quality custom injection molded products to meet each customer''s unique specifications.", "founded_year": "1979", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ITAR Compliant"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ironwood-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Isoflex Packaging, headquartered in Vancouver, Washington, was founded in 1985 with the goal of introducing a new approach to the film industry.

The company produces specialty films for laminating, printing, coating, and converting markets. Its seven U.S. facilities run 24/7/365 on monolayer, three-, five-, and seven-layer co-extrusion lines, delivering a combined film and bag capacity of 350 million pounds per year. Core capabilities include high-performance barrier films, shrink films, custom bags, auto-insert packaging, non-shrink sheeting, and stretch hood films.

Isoflex serves food and beverage, consumer goods, institutional, industrial, agricultural, and medical/pharmaceutical sectors.

Founded to pioneer a different way of making films, Isoflex emphasizes custom-engineered solutions for difficult packaging challenges. The company highlights sustainable manufacturing, offering How2Recycle®-labeled, post-consumer recycled, bio-based, compostable, and antimicrobial film options.', certifications=ARRAY['NMSDC','SQF']::text[], profile='{"capabilities": ["High-performance barrier film extrusion", "Shrink film extrusion", "Specialty film extrusion", "Custom bag manufacturing", "Auto-insert packaging", "Non-shrink sheeting", "Stretch hood film production", "Monolayer co-extrusion", "Three-layer co-extrusion", "Five-layer co-extrusion", "Seven-layer high-barrier co-extrusion", "Laminating", "Printing", "Coating", "Converting", "Custom-engineered flexible packaging solutions"], "industries": ["Food & Beverage", "Consumer Goods", "Institutional", "Industrial", "Agricultural", "Medical/Pharmaceutical"], "materials": ["Polyethylene (PE)", "Post-consumer recycled (PCR) resin", "Bio-based resins", "Compostable resins", "Antimicrobial additives"], "equipment": ["Monolayer co-extrusion lines", "Three-layer co-extrusion lines", "Five-layer co-extrusion lines", "Seven-layer high-barrier co-extrusion lines"], "volume": "350 million pounds annual capacity", "lead_time": "", "tolerances": "", "built_on": ["Largest privately-owned film extrusion group in the U.S., Canada, and Central America", "Seven strategically located U.S. facilities enabling coast-to-coast service", "24/7/365 production on multi-layer co-extrusion lines", "NMSDC and SQF certified", "Sustainable film options including How2Recycle\u00ae, PCR, bio-based, compostable, and antimicrobial"], "facts_used": ["Founded in 1985 -> db description", "Headquartered in Vancouver, Washington -> db hq_city, hq_state_label", "Seven U.S. facilities -> page /", "350 million pounds annual capacity -> page /", "Monolayer, three-layer, five-layer, seven-layer co-extrusion lines -> page /", "24/7/365 production -> page /",